<?php
require_once __DIR__.'/../config/app.php';require_once __DIR__.'/../config/koneksi.php';require_admin();$pageTitle='Data Pembimbing';$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);$nama=trim($_POST['nama']??'');$nip=trim($_POST['nip']??'');$no_hp=trim($_POST['no_hp']??'');$email=trim($_POST['email']??'');
 if($a==='delete'){$pdo->prepare("DELETE FROM pembimbing WHERE id=?")->execute([$id]);flash('success','Data pembimbing dihapus.');redirect('pembimbing.php');}
 if($nama==='')$errors[]='Nama pembimbing wajib diisi.';if(!$errors){if($a==='create')$q=$pdo->prepare("INSERT INTO pembimbing(nama,nip,no_hp,email) VALUES(?,?,?,?)");else $q=$pdo->prepare("UPDATE pembimbing SET nama=?,nip=?,no_hp=?,email=? WHERE id=?");$a==='create'?$q->execute([$nama,$nip,$no_hp,$email]):$q->execute([$nama,$nip,$no_hp,$email,$id]);flash('success','Data pembimbing disimpan.');redirect('pembimbing.php');}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare("SELECT * FROM pembimbing WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();}$search=trim($_GET['q']??'');$q=$pdo->prepare("SELECT * FROM pembimbing WHERE nama LIKE ? OR nip LIKE ? ORDER BY nama");$q->execute(["%$search%","%$search%"]);$rows=$q->fetchAll();include __DIR__.'/../partials/header.php';?>
<div class="page-head"><div><h1>Data Pembimbing</h1><div class="muted">Kelola guru pembimbing PKL.</div></div></div><?php foreach($errors as $x):?><div class="alert danger"><?=e($x)?></div><?php endforeach;?>
<div class="card"><h3><?=$edit?'Edit Pembimbing':'Tambah Pembimbing'?></h3><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="<?=$edit?'update':'create'?>"><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="form-grid"><?php foreach([['nama','Nama Lengkap'],['nip','NIP'],['no_hp','No. HP'],['email','Email']] as $f):?><div class="field"><label><?=e($f[1])?><?= $f[0]==='nama'?' *':''?></label><input name="<?=e($f[0])?>" value="<?=e($edit[$f[0]]??'')?>" <?=$f[0]==='nama'?'required':''?>></div><?php endforeach;?></div><div class="form-actions"><button class="btn">Simpan</button><?php if($edit):?><a class="btn secondary" href="pembimbing.php">Batal</a><?php endif;?></div></form></div>
<div class="card"><form class="filters"><input name="q" value="<?=e($search)?>" placeholder="Cari nama/NIP"><button class="btn">Cari</button></form><div class="table-wrap"><table><thead><tr><th>Nama</th><th>NIP</th><th>No. HP</th><th>Email</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nama'])?></td><td><?=e($r['nip'])?></td><td><?=e($r['no_hp'])?></td><td><?=e($r['email'])?></td><td><div class="actions"><a class="btn secondary small" href="?edit=<?=$r['id']?>">Edit</a><form method="post" data-confirm="Hapus pembimbing ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn danger small">Hapus</button></form></div></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="empty">Belum ada pembimbing.</td></tr><?php endif;?></tbody></table></div></div><?php include __DIR__.'/../partials/footer.php';?>
